#define FNV_OFFSET UINT64_C(1469598103934665603)
#define FNV_PRIME UINT64_C(1099511628211)
#define SUMMARY_PAYLOAD_SIZE 97u
#define HISTOGRAM_PAYLOAD_SIZE 569u
#define SPATIAL_PAYLOAD_SIZE 5262u

static uint64_t hash_bytes(const void *data,size_t n){const unsigned char*p=data;uint64_t h=FNV_OFFSET;while(n--){h^=*p++;h*=FNV_PRIME;}return h;}
static bool add_u64(uint64_t *v,uint64_t n){if(*v>UINT64_MAX-n)return false;*v+=n;return true;}
static void put_u64(unsigned char *p,uint64_t v){unsigned i;for(i=0;i<8;i++)p[i]=(unsigned char)(v>>(i*8u));}
static uint64_t get_u64(const unsigned char *p){uint64_t v=0;unsigned i;for(i=0;i<8;i++)v|=(uint64_t)p[i]<<(i*8u);return v;}
static void put_u32(unsigned char*p,uint32_t v){unsigned i;for(i=0;i<4;i++)p[i]=(unsigned char)(v>>(i*8u));}
static uint32_t get_u32(const unsigned char*p){uint32_t v=0;unsigned i;for(i=0;i<4;i++)v|=(uint32_t)p[i]<<(i*8u);return v;}

fractal_result fractal_field_descriptor_validate(const fractal_field_descriptor*d,size_t element,size_t*required){size_t row;if(!d||!required||!element||!d->width||!d->height||d->format!=FRACTAL_FIELD_ITERATION_CLASSIFICATION_V1)return FRACTAL_ERROR_INVALID_SPEC;if(d->width>SIZE_MAX/element)return FRACTAL_ERROR_INVALID_SPEC;row=(size_t)d->width*element;if(d->stride<row||d->height>SIZE_MAX/d->stride)return FRACTAL_ERROR_INVALID_SPEC;*required=d->stride*d->height;return FRACTAL_OK;}
fractal_result fractal_field_view_validate(const fractal_field_view*v,size_t e){size_t n;if(!v||!v->data||fractal_field_descriptor_validate(&v->descriptor,e,&n)!=FRACTAL_OK||v->data_size<n)return FRACTAL_ERROR_INVALID_SPEC;return FRACTAL_OK;}
fractal_result fractal_mutable_field_view_validate(const fractal_mutable_field_view*v,size_t e){fractal_field_view x;if(!v)return FRACTAL_ERROR_INVALID_SPEC;x=(fractal_field_view){v->descriptor,v->data,v->data_size};return fractal_field_view_validate(&x,e);}

fractal_result fractal_analysis_request_serialize(const fractal_analysis_request*r,char*b,size_t c,size_t*l){int n;if(!r||!r->analyzer_id||!l||r->output_mode>FRACTAL_ANALYSIS_COPY_OUTPUT)return FRACTAL_ERROR_INVALID_SPEC;n=snprintf(b,c,"{\"analyzer\":\"%s\",\"mode\":%u,\"preserve\":%s,\"record_capacity\":%zu,\"records\":%s}",r->analyzer_id,(unsigned)r->output_mode,r->require_field_preservation?"true":"false",r->record_capacity,r->require_records?"true":"false");*l=n<0?0u:(size_t)n;return n<0||!b||c<=(size_t)n?FRACTAL_ERROR_BUFFER_TOO_SMALL:FRACTAL_OK;}
static const char* schema_id_for(const char*id){if(!id)return "";if(!strcmp(id,"fractal.analyzer.escape-classification-summary"))return FRACTAL_ESCAPE_SUMMARY_SCHEMA_ID;if(!strcmp(id,"fractal.analyzer.iteration-histogram"))return FRACTAL_ITERATION_HISTOGRAM_SCHEMA_ID;if(!strcmp(id,"fractal.analyzer.spatial-workload-grid"))return FRACTAL_SPATIAL_WORKLOAD_SCHEMA_ID;return "";}
static uint32_t schema_version_for(const char*id){return *schema_id_for(id)?1u:0u;}
fractal_result fractal_analysis_pipeline_init_many(fractal_analysis_pipeline*p,const fractal_analyzer_vtable*const*a,const fractal_analysis_request*r,size_t count){char canonical[4096];size_t used=0,i,total=0;int n;if(!p||count>FRACTAL_ANALYZER_CHAIN_MAX||((!a||!r)&&count))return FRACTAL_ERROR_INVALID_ARGUMENT;memset(p,0,sizeof(*p));for(i=0;i<count;i++){size_t j;if(!a[i]||!a[i]->descriptor||!r[i].analyzer_id||strcmp(a[i]->descriptor->module_id,r[i].analyzer_id)||fractal_module_descriptor_validate(a[i]->descriptor,FRACTAL_MODULE_ANALYZER)!=FRACTAL_OK)return FRACTAL_ERROR_INVALID_SPEC;for(j=0;j<i;j++)if(!strcmp(r[j].analyzer_id,r[i].analyzer_id))return FRACTAL_ERROR_INVALID_SPEC;if(total>SIZE_MAX-r[i].record_capacity)return FRACTAL_ERROR_INVALID_SPEC;total+=r[i].record_capacity;p->analyzers[i]=a[i];p->requests[i]=r[i];}if(total>FRACTAL_ANALYSIS_MAX_RECORDS)return FRACTAL_ERROR_BUFFER_TOO_SMALL;p->count=count;n=snprintf(canonical,sizeof(canonical),"{\"abi\":%u,\"analyzers\":[",FRACTAL_ANALYZER_CHAIN_ABI_VERSION);if(n<0||(size_t)n>=sizeof(canonical))return FRACTAL_ERROR_INVALID_SPEC;used=(size_t)n;for(i=0;i<count;i++){n=snprintf(canonical+used,sizeof(canonical)-used,"%s{\"analyzer\":\"%s\",\"analyzer_version\":%u,\"mode\":%u,\"records\":%zu,\"schema\":\"%s\",\"schema_version\":%u}",i?",":"",r[i].analyzer_id,a[i]->descriptor->module_version,(unsigned)r[i].output_mode,r[i].record_capacity,schema_id_for(r[i].analyzer_id),schema_version_for(r[i].analyzer_id));if(n<0||(size_t)n>=sizeof(canonical)-used)return FRACTAL_ERROR_INVALID_SPEC;used+=(size_t)n;}n=snprintf(canonical+used,sizeof(canonical)-used,"],\"count\":%zu,\"records\":%zu}",count,total);if(n<0||(size_t)n>=sizeof(canonical)-used)return FRACTAL_ERROR_INVALID_SPEC;used+=(size_t)n;p->identity=hash_bytes(canonical,used);return FRACTAL_OK;}
fractal_result fractal_analysis_pipeline_init(fractal_analysis_pipeline*p,const fractal_analyzer_vtable*a,const fractal_analysis_request*r){const fractal_analyzer_vtable*items[1];if(!a&&!r)return fractal_analysis_pipeline_init_many(p,NULL,NULL,0);if(!a||!r)return FRACTAL_ERROR_INVALID_SPEC;items[0]=a;return fractal_analysis_pipeline_init_many(p,items,r,1);}
fractal_result fractal_analysis_pipeline_serialize(const fractal_analysis_pipeline*p,char*b,size_t c,size_t*l){size_t used=0,i,total=0;int n;if(!p||!l||p->count>FRACTAL_ANALYZER_CHAIN_MAX)return FRACTAL_ERROR_INVALID_SPEC;for(i=0;i<p->count;i++)total+=p->requests[i].record_capacity;n=snprintf(b,c,"{\"abi\":%u,\"analyzers\":[",FRACTAL_ANALYZER_CHAIN_ABI_VERSION);if(n<0)return FRACTAL_ERROR_INVALID_SPEC;used=(size_t)n;for(i=0;i<p->count;i++){n=snprintf(b&&used<c?b+used:NULL,used<c?c-used:0,"%s{\"analyzer\":\"%s\",\"analyzer_version\":%u,\"mode\":%u,\"ordinal\":%zu,\"records\":%zu,\"schema\":\"%s\",\"schema_version\":%u}",i?",":"",p->requests[i].analyzer_id,p->analyzers[i]->descriptor->module_version,(unsigned)p->requests[i].output_mode,i,p->requests[i].record_capacity,schema_id_for(p->requests[i].analyzer_id),schema_version_for(p->requests[i].analyzer_id));if(n<0)return FRACTAL_ERROR_INVALID_SPEC;used+=(size_t)n;}n=snprintf(b&&used<c?b+used:NULL,used<c?c-used:0,"],\"count\":%zu,\"identity\":\"%016" PRIx64 "\",\"records\":%zu}",p->count,p->identity,total);if(n<0)return FRACTAL_ERROR_INVALID_SPEC;used+=(size_t)n;*l=used;return !b||c<=used?FRACTAL_ERROR_BUFFER_TOO_SMALL:FRACTAL_OK;}
fractal_result fractal_analysis_pipeline_validate(const fractal_analysis_pipeline*p,const fractal_field_descriptor*d,size_t capacity){size_t i,total=0;if(!p||!d||p->count>FRACTAL_ANALYZER_CHAIN_MAX)return FRACTAL_ERROR_INVALID_SPEC;for(i=0;i<p->count;i++){if(total>SIZE_MAX-p->requests[i].record_capacity)return FRACTAL_ERROR_INVALID_SPEC;total+=p->requests[i].record_capacity;if(p->analyzers[i]->validate(&p->requests[i],d)!=FRACTAL_OK)return FRACTAL_ERROR_INVALID_SPEC;}return total>capacity?FRACTAL_ERROR_BUFFER_TOO_SMALL:FRACTAL_OK;}
fractal_result fractal_analysis_pipeline_run(const fractal_analysis_pipeline*p,const fractal_field_view*source,const fractal_cancellation*c,fractal_analysis_result*out,size_t capacity){fractal_analysis_result aggregate={0};size_t i,total=0;if(!p||!source||!out)return FRACTAL_ERROR_INVALID_ARGUMENT;if(fractal_analysis_pipeline_validate(p,&source->descriptor,capacity)!=FRACTAL_OK)return fractal_analysis_pipeline_validate(p,&source->descriptor,capacity);for(i=0;i<p->count;i++)total+=p->requests[i].record_capacity;aggregate.identity=p->identity;aggregate.chain_version=FRACTAL_ANALYZER_CHAIN_ABI_VERSION;aggregate.analyzer_count=p->count;aggregate.records_required=total;aggregate.source_field_checksum=fractal_checksum64(source->data,source->data_size);aggregate.output_field_checksum=aggregate.source_field_checksum;aggregate.field_preserved=true;aggregate.result=FRACTAL_OK;for(i=0;i<p->count;i++){fractal_analyzer_state state={0};fractal_analysis_result one={0};fractal_field_view final={0};size_t j;if(c&&c->requested){aggregate.cancelled=true;aggregate.result=FRACTAL_ERROR_CANCELLED;return FRACTAL_ERROR_CANCELLED;}if(p->analyzers[i]->begin(&state,&p->requests[i],aggregate.source_field_checksum)!=FRACTAL_OK)return FRACTAL_ERROR_INVALID_SPEC;if(p->analyzers[i]->process(&state,source,NULL,&final,c)!=FRACTAL_OK){fractal_result failure=state.result.result;p->analyzers[i]->abort(&state);return failure==FRACTAL_OK?FRACTAL_ERROR_INVALID_SPEC:failure;}if(final.data!=source->data||final.data_size!=source->data_size){p->analyzers[i]->abort(&state);return FRACTAL_ERROR_INVALID_SPEC;}if(p->analyzers[i]->finish(&state,&one)!=FRACTAL_OK)return FRACTAL_ERROR_INVALID_SPEC;if(!one.field_preserved||one.output_field_checksum!=aggregate.source_field_checksum||aggregate.records_produced>capacity-one.records_produced)return FRACTAL_ERROR_INVALID_SPEC;for(j=0;j<one.records_produced;j++){fractal_analysis_record record=one.records[j];record.analyzer_id=p->requests[i].analyzer_id;record.analyzer_version=p->analyzers[i]->descriptor->module_version;record.schema_id=schema_id_for(record.analyzer_id);record.chain_ordinal=(uint32_t)i;record.status=FRACTAL_OK;aggregate.records[aggregate.records_produced++]=record;}if(UINT64_MAX-aggregate.samples_examined<one.samples_examined)return FRACTAL_ERROR_INVALID_SPEC;aggregate.samples_examined+=one.samples_examined;}*out=aggregate;return FRACTAL_OK;}

fractal_result fractal_escape_summary_record_decode(const fractal_analysis_record*r,fractal_escape_classification_summary_v1*s){uint64_t *values[12];unsigned i;if(!r||!s||r->type_id!=FRACTAL_ANALYSIS_RECORD_ESCAPE_SUMMARY||r->schema_version!=FRACTAL_ESCAPE_SUMMARY_SCHEMA_VERSION||r->payload_size!=SUMMARY_PAYLOAD_SIZE)return FRACTAL_ERROR_INVALID_SPEC;memset(s,0,sizeof(*s));values[0]=&s->samples_total;values[1]=&s->escaped_samples;values[2]=&s->bounded_samples;values[3]=&s->unresolved_samples;values[4]=&s->maximum_iteration_samples;values[5]=&s->cancelled_samples;values[6]=&s->failed_samples;values[7]=&s->other_classified_samples;values[8]=&s->iteration_samples;values[9]=&s->iterations_min;values[10]=&s->iterations_max;values[11]=&s->iterations_sum;for(i=0;i<12;i++)*values[i]=get_u64(r->payload+i*8u);if(r->payload[96]>1)return FRACTAL_ERROR_INVALID_SPEC;s->iteration_statistics_valid=r->payload[96]!=0;return FRACTAL_OK;}
size_t fractal_iteration_histogram_bucket_v1(uint64_t v){size_t b;if(v<3)return (size_t)v;for(b=3;b<63;b++)if(v<=(UINT64_C(1)<<(b-1u)))return b;return 63u;}
fractal_result fractal_iteration_histogram_record_decode(const fractal_analysis_record*r,fractal_iteration_histogram_v1*h){uint64_t *values[7];unsigned i;if(!r||!h||r->type_id!=FRACTAL_ANALYSIS_RECORD_ITERATION_HISTOGRAM||r->schema_version!=FRACTAL_ITERATION_HISTOGRAM_SCHEMA_VERSION||r->payload_size!=HISTOGRAM_PAYLOAD_SIZE)return FRACTAL_ERROR_INVALID_SPEC;memset(h,0,sizeof(*h));for(i=0;i<64;i++)h->bins[i]=get_u64(r->payload+i*8u);values[0]=&h->eligible_samples;values[1]=&h->excluded_samples;values[2]=&h->total_samples;values[3]=&h->minimum_iteration;values[4]=&h->maximum_iteration;values[5]=&h->summed_iterations;values[6]=&h->overflow_bin_count;for(i=0;i<7;i++)*values[i]=get_u64(r->payload+512u+i*8u);if(r->payload[568]>1)return FRACTAL_ERROR_INVALID_SPEC;h->histogram_valid=r->payload[568]!=0;return FRACTAL_OK;}
fractal_result fractal_spatial_workload_cell_index_v1(uint32_t x,uint32_t y,uint32_t width,uint32_t height,size_t*out){uint64_t sx,sy;if(!out||!width||!height||x>=width||y>=height)return FRACTAL_ERROR_INVALID_SPEC;/* Повышение типа предшествует умножению; uint32 * 8 всегда помещается в uint64. */sx=(uint64_t)x*FRACTAL_SPATIAL_WORKLOAD_GRID_WIDTH/width;sy=(uint64_t)y*FRACTAL_SPATIAL_WORKLOAD_GRID_HEIGHT/height;if(sx>=8||sy>=8)return FRACTAL_ERROR_INVALID_SPEC;*out=(size_t)(sy*8u+sx);return FRACTAL_OK;}
fractal_result fractal_spatial_workload_record_decode(const fractal_analysis_record*r,fractal_spatial_workload_grid_v1*g){unsigned i,j;const unsigned char*p;if(!r||!g||r->type_id!=FRACTAL_ANALYSIS_RECORD_SPATIAL_WORKLOAD_GRID||r->schema_version!=1||r->payload_size!=SPATIAL_PAYLOAD_SIZE)return FRACTAL_ERROR_INVALID_SPEC;memset(g,0,sizeof(*g));for(i=0;i<64;i++){uint64_t*v[10]={&g->cells[i].samples,&g->cells[i].escaped,&g->cells[i].bounded,&g->cells[i].unresolved,&g->cells[i].cancelled,&g->cells[i].failed,&g->cells[i].eligible_samples,&g->cells[i].minimum_iteration,&g->cells[i].maximum_iteration,&g->cells[i].summed_iterations};p=r->payload+i*81u;for(j=0;j<10;j++)*v[j]=get_u64(p+j*8u);if(p[80]>1)return FRACTAL_ERROR_INVALID_SPEC;g->cells[i].iteration_statistics_valid=p[80]!=0;}p=r->payload+5184u;g->grid_width=(uint32_t)get_u64(p);g->grid_height=(uint32_t)get_u64(p+8);g->source_width=(uint32_t)get_u64(p+16);g->source_height=(uint32_t)get_u64(p+24);g->total_samples=get_u64(p+32);g->total_eligible_samples=get_u64(p+40);g->minimum_iteration=get_u64(p+48);g->maximum_iteration=get_u64(p+56);g->summed_iterations=get_u64(p+64);if(p[72]>1||p[73]>1)return FRACTAL_ERROR_INVALID_SPEC;g->iteration_statistics_valid=p[72]!=0;g->classification_conserved=p[73]!=0;g->result_status=(fractal_result)get_u32(p+74);return g->grid_width==8&&g->grid_height==8?FRACTAL_OK:FRACTAL_ERROR_INVALID_SPEC;}
