fractal_result fractal_analysis_records_serialize(const fractal_analysis_record*r,size_t count,char*b,size_t c,size_t*l){char record[32768];size_t rn;int n;if(!l||(!r&&count)||count>FRACTAL_ANALYSIS_MAX_RECORDS)return FRACTAL_ERROR_INVALID_ARGUMENT;if(!count){*l=2;if(!b||c<3)return FRACTAL_ERROR_BUFFER_TOO_SMALL;memcpy(b,"[]",3);return FRACTAL_OK;}if(fractal_analysis_record_serialize(r,record,sizeof(record),&rn)!=FRACTAL_OK)return FRACTAL_ERROR_INVALID_SPEC;n=snprintf(b,c,"[%s]",record);*l=n<0?0u:(size_t)n;return n<0||!b||c<=(size_t)n?FRACTAL_ERROR_BUFFER_TOO_SMALL:FRACTAL_OK;}
